1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18		"sort"
19		"strings"
20	)
21	
22	// SnapshotFormatVersion is the only on-disk snapshot format understood.
23	const SnapshotFormatVersion = 1
24	
25	// SnapshotFile is the on-disk representation of one frozen lineage graph.
26	//
27	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
28	// verified against Graph on every read; Graph carries the complete graph.
29	type SnapshotFile struct {
30		FormatVersion int       `json:"formatVersion"`
31		ContentID     string    `json:"contentId"`
32		Graph         GraphFile `json:"graph"`
33	}
34	
35	// RootSourceChange reports that one dataset present in BOTH versions reaches a
36	// different set of root sources. OldRoots and NewRoots are sorted by name and
37	// never nil, so empty root sets encode as [] rather than null.
38	type RootSourceChange struct {
39		Dataset  string   `json:"dataset"`
40		OldRoots []string `json:"oldRoots"`
41		NewRoots []string `json:"newRoots"`
42	}
43	
44	// CompareReport is the deterministic, read-only diff of two snapshots read in
45	// the fixed direction old -> new.
46	//
47	// NewDatasets and RemovedDatasets list nodes present on only one side.
48	// ChangedDatasets lists datasets present on both sides whose direct upstream
49	// set actually changed. AddedRelations and RemovedRelations list every
50	// directed edge present on only one side, including edges that vanish because
51	// one endpoint node was removed. RootSourceChanges covers only datasets common
52	// to both versions whose reachable root set differs; added or removed datasets
53	// never appear there.
54	type CompareReport struct {
55		NewDatasets       []string           `json:"newDatasets"`
56		RemovedDatasets   []string           `json:"removedDatasets"`
57		ChangedDatasets   []string           `json:"changedDatasets"`
58		AddedRelations    []Relation         `json:"addedRelations"`
59		RemovedRelations  []Relation         `json:"removedRelations"`
60		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
61	}
62	
63	// contentIDPrefix names the hash algorithm used for content addressing.
64	const contentIDPrefix = "sha256:"
65	
66	// canonicalGraph serializes the graph's semantics deterministically: datasets
67	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
68	// JSON with no insignificant whitespace. Two semantically equal graphs always
69	// produce identical bytes.
70	func canonicalGraph(adj adjacency) ([]byte, error) {
71		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
72		return json.Marshal(gf)
73	}
74	
75	// computeContentID returns the content identifier of the graph bytes:
76	// "sha256:" followed by the lowercase hex SHA-256 digest.
77	func computeContentID(canonical []byte) string {
78		sum := sha256.Sum256(canonical)
79		return contentIDPrefix + hex.EncodeToString(sum[:])
80	}
81	
82	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
83	// version 1 and the matching content identifier. It does not mutate graph. The
84	// returned document and its serialized bytes depend only on graph semantics.
85	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
86		if err := ValidateGraph(graph); err != nil {
87			return nil, err
88		}
89		adj, err := graphAdjacency(graph)
90		if err != nil {
91			return nil, err
92		}
93		canonical, err := canonicalGraph(adj)
94		if err != nil {
95			return nil, err
96		}
97		return &SnapshotFile{
98			FormatVersion: SnapshotFormatVersion,
99			ContentID:     computeContentID(canonical),
100			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
101		}, nil
102	}
103	
104	// MarshalSnapshot serializes a snapshot the same way for every save: indented
105	// JSON keyed by struct field order, terminated by a single newline.
106	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
107		var buf bytes.Buffer
108		enc := json.NewEncoder(&buf)
109		enc.SetIndent("", "  ")
110		enc.SetEscapeHTML(false)
111		if err := enc.Encode(snap); err != nil {
112			return nil, err
113		}
114		return buf.Bytes(), nil
115	}
116	
117	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
118	// can distinguish "field absent" from "field present with a zero value"
119	// (e.g. a missing formatVersion must be rejected rather than read as 0).
120	type rawSnapshot struct {
121		FormatVersion json.RawMessage `json:"formatVersion"`
122		ContentID     json.RawMessage `json:"contentId"`
123		Graph         json.RawMessage `json:"graph"`
124	}
125	
126	// isJSONNull reports whether a raw JSON value is the literal null.
127	func isJSONNull(raw json.RawMessage) bool {
128		return string(bytes.TrimSpace(raw)) == "null"
129	}
130	
131	// ParseSnapshot parses and strictly validates one snapshot document: required
132	// fields must be present and well-typed, no known field may be declared twice
133	// within the same object (even with identical values, a null first, or a
134	// spelling equivalent under Unicode case folding or JSON escaping), the
135	// format version must be supported, the embedded graph must be structurally
136	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
137	// and the content identifier must correspond exactly to the graph. A
138	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
139	// can never be trusted as a version.
140	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
141		if err := checkDuplicateFields(data); err != nil {
142			return nil, err
143		}
144		var raw rawSnapshot
145		if err := json.Unmarshal(data, &raw); err != nil {
146			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
147		}
148		if len(raw.FormatVersion) == 0 {
149			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
150		}
151		if len(raw.ContentID) == 0 {
152			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
153		}
154		if len(raw.Graph) == 0 {
155			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
156		}
157		// An explicit JSON null is present-but-untyped and must not be silently
158		// treated as a zero value (in particular, graph:null must not read as an
159		// empty graph).
160		if isJSONNull(raw.FormatVersion) {
161			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
162		}
163		if isJSONNull(raw.ContentID) {
164			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
165		}
166		if isJSONNull(raw.Graph) {
167			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
168		}
169	
170		var version int
171		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
172			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
173		}
174		if version != SnapshotFormatVersion {
175			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
176		}
177	
178		var contentID string
179		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
180			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
181		}
182		if contentID == "" {
183			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
184		}
185	
186		var gf GraphFile
187		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
188			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
189		}
190		// The embedded graph obeys exactly the same structural rules as a
191		// standalone graph file, so the two readers can never judge one graph
192		// differently.
193		adj, err := validateGraphStructureFromFile(gf.Datasets)
194		if err != nil {
195			return nil, err
196		}
197	
198		canonical, err := canonicalGraph(adj)
199		if err != nil {
200			return nil, err
201		}
202		if want := computeContentID(canonical); contentID != want {
203			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
204		}
205	
206		return &SnapshotFile{
207			FormatVersion: version,
208			ContentID:     contentID,
209			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
210		}, nil
211	}
212	
213	// errAbortScan stops the duplicate-field scan when the document is too
214	// malformed to keep walking; the regular parse then reports the syntax or
215	// type error instead.
216	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
217	
218	// checkDuplicateFields rejects a snapshot in which a known field is declared
219	// more than once within the same object: formatVersion, contentId, and graph
220	// at the top level, datasets inside graph, and name and upstreams inside each
221	// dataset record. A repeated field is ambiguous — the reader would silently
222	// keep only one declaration — so the whole snapshot is refused even when the
223	// duplicates carry identical values, the first is null, or the surviving value
224	// would pass every other check.
225	//
226	// The decoder uses UseNumber so numbers are kept verbatim instead of being
227	// converted to float64: a perfectly legal JSON number outside the float64
228	// range (such as 1e400), even one buried in an ignored unknown field's value,
229	// must not make the decoder error out and abort the whole scan — otherwise an
230	// unrelated large number placed before a repeated known field would hide that
231	// duplication. Malformed number syntax still fails and is left to the regular
232	// parse to report.
233	//
234	// Field names are compared after JSON string unescaping and with the same
235	// Unicode simple case-folding the decoder applies to its case-insensitive
236	// field lookup (equivalent to strings.EqualFold), so "name", "Name", and
237	// "name" all collide, and so do spellings that only differ in a fold
238	// equivalent rune such as "formatVerſion" (long s) and "formatVersion".
239	// Unknown fields keep their ignore-everything behavior and may repeat freely.
240	// Documents that are not shaped like a snapshot at all are left to the
241	// regular parse, which reports the structural problem.
242	func checkDuplicateFields(data []byte) error {
243		dec := json.NewDecoder(bytes.NewReader(data))
244		dec.UseNumber()
245		err := checkTopLevelObject(dec)
246		if errors.Is(err, errAbortScan) {
247			return nil
248		}
249		return err
250	}
251	
252	// checkGraphFileDuplicateFields applies the same repeated-known-field rule to
253	// a standalone graph file: datasets may be declared only once in the
254	// top-level graph object, and name and upstreams only once in each dataset
255	// record. This keeps UnmarshalGraphFile in lockstep with ParseSnapshot, which
256	// runs the identical scan on the embedded graph, so preview, apply, and
257	// snapshot can never disagree about a graph file that repeats a known field.
258	func checkGraphFileDuplicateFields(data []byte) error {
259		dec := json.NewDecoder(bytes.NewReader(data))
260		dec.UseNumber()
261		err := checkGraphValue(dec, "at the top level of the graph")
262		if errors.Is(err, errAbortScan) {
263			return nil
264		}
265		return err
266	}
267	
268	// checkTopLevelObject scans the top-level snapshot object for repeated
269	// formatVersion/contentId/graph declarations, descending into graph values.
270	func checkTopLevelObject(dec *json.Decoder) error {
271		tok, err := scanToken(dec)
272		if err != nil {
273			return err
274		}
275		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
276			return nil // not an object: the regular parse reports the type error
277		}
278		seen := make(map[string]bool, 3)
279		for dec.More() {
280			key, err := scanKey(dec)
281			if err != nil {
282				return err
283			}
284			field, known := snapshotField(key)
285			if known {
286				if seen[field] {
287					return duplicateFieldError(field, "at the top level of the snapshot")
288				}
289				seen[field] = true
290			}
291			if field == "graph" {
292				if err := checkGraphValue(dec, `in "graph"`); err != nil {
293					return err
294				}
295			} else if err := skipValue(dec); err != nil {
296				return err
297			}
298		}
299		_, err = scanToken(dec) // closing '}'
300		return err
301	}
302	
303	// checkGraphValue scans one graph value for a repeated datasets declaration,
304	// descending into each dataset record of the datasets array. location names
305	// the graph object itself in the duplicate error ("in \"graph\"" when the
306	// graph is embedded in a snapshot, the top-level description for a standalone
307	// graph file).
308	func checkGraphValue(dec *json.Decoder, location string) error {
309		tok, err := scanToken(dec)
310		if err != nil {
311			return err
312		}
313		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
314			// Not an object (null, array, scalar): consume any remainder and let
315			// the regular parse report the type problem.
316			return skipRest(dec, tok)
317		}
318		seen := false
319		for dec.More() {
320			key, err := scanKey(dec)
321			if err != nil {
322				return err
323			}
324			if strings.EqualFold(key, "datasets") {
325				if seen {
326					return duplicateFieldError("datasets", location)
327				}
328				seen = true
329				if err := checkDatasetsValue(dec); err != nil {
330					return err
331				}
332			} else if err := skipValue(dec); err != nil {
333				return err
334			}
335		}
336		_, err = scanToken(dec) // closing '}'
337		return err
338	}
339	
340	// checkDatasetsValue scans one datasets array, checking every record that is
341	// an object for repeated name/upstreams declarations.
342	func checkDatasetsValue(dec *json.Decoder) error {
343		tok, err := scanToken(dec)
344		if err != nil {
345			return err
346		}
347		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
348			return skipRest(dec, tok) // not an array: the regular parse reports it
349		}
350		for index := 0; dec.More(); index++ {
351			if err := checkDatasetRecord(dec, index); err != nil {
352				return err
353			}
354		}
355		_, err = scanToken(dec) // closing ']'
356		return err
357	}
358	
359	// checkDatasetRecord scans one element of the datasets array. If it is an
360	// object, name and upstreams must each be declared at most once.
361	func checkDatasetRecord(dec *json.Decoder, index int) error {
362		tok, err := scanToken(dec)
363		if err != nil {
364			return err
365		}
366		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
367			return skipRest(dec, tok) // not an object: the regular parse reports it
368		}
369		seen := make(map[string]bool, 2)
370		for dec.More() {
371			key, err := scanKey(dec)
372			if err != nil {
373				return err
374			}
375			if field, known := datasetField(key); known {
376				if seen[field] {
377					return duplicateFieldError(field, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index))
378				}
379				seen[field] = true
380			}
381			if err := skipValue(dec); err != nil {
382				return err
383			}
384		}
385		_, err = scanToken(dec) // closing '}'
386		return err
387	}
388	
389	// duplicateFieldError reports a known field declared twice, naming the field
390	// and where in the document the repetition occurred.
391	func duplicateFieldError(field, location string) error {
392		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
393	}
394	
395	// snapshotField maps a top-level key to the canonical name of the snapshot
396	// field it selects, matching the decoder's case-insensitive field lookup.
397	func snapshotField(key string) (string, bool) {
398		switch {
399		case strings.EqualFold(key, "formatVersion"):
400			return "formatVersion", true
401		case strings.EqualFold(key, "contentId"):
402			return "contentId", true
403		case strings.EqualFold(key, "graph"):
404			return "graph", true
405		}
406		return "", false
407	}
408	
409	// datasetField maps a dataset-record key to the canonical name of the record
410	// field it selects, matching the decoder's case-insensitive field lookup.
411	func datasetField(key string) (string, bool) {
412		switch {
413		case strings.EqualFold(key, "name"):
414			return "name", true
415		case strings.EqualFold(key, "upstreams"):
416			return "upstreams", true
417		}
418		return "", false
419	}
420	
421	// scanToken reads one token; any decode failure aborts the scan so the
422	// regular parse can report the malformed document.
423	func scanToken(dec *json.Decoder) (json.Token, error) {
424		tok, err := dec.Token()
425		if err != nil {
426			return nil, errAbortScan
427		}
428		return tok, nil
429	}
430	
431	// scanKey reads the next key of the object currently being walked.
432	func scanKey(dec *json.Decoder) (string, error) {
433		tok, err := scanToken(dec)
434		if err != nil {
435			return "", err
436		}
437		key, ok := tok.(string)
438		if !ok {
439			return "", errAbortScan
440		}
441		return key, nil
442	}
443	
444	// skipValue consumes one complete JSON value.
445	func skipValue(dec *json.Decoder) error {
446		tok, err := scanToken(dec)
447		if err != nil {
448			return err
449		}
450		return skipRest(dec, tok)
451	}
452	
453	// skipRest consumes the remainder of a value whose first token is tok.
454	func skipRest(dec *json.Decoder, tok json.Token) error {
455		delim, ok := tok.(json.Delim)
456		if !ok {
457			return nil // scalar, fully consumed already
458		}
459		var closer json.Delim
460		switch delim {
461		case '{':
462			closer = '}'
463			for dec.More() {
464				if _, err := scanKey(dec); err != nil {
465					return err
466				}
467				if err := skipValue(dec); err != nil {
468					return err
469				}
470			}
471		case '[':
472			closer = ']'
473			for dec.More() {
474				if err := skipValue(dec); err != nil {
475					return err
476				}
477			}
478		default:
479			return errAbortScan
480		}
481		tok, err := scanToken(dec)
482		if err != nil {
483			return err
484		}
485		if end, ok := tok.(json.Delim); !ok || end != closer {
486			return errAbortScan
487		}
488		return nil
489	}
490	
491	// CompareSnapshots returns the fixed-direction diff from old to new. Both
492	// inputs are assumed to have passed ParseSnapshot; the report is fully
493	// deterministic and identical for semantically identical comparisons.
494	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
495		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
496		newAdj := adjacencyFromValidFile(newSnap.Graph)
497	
498		added, removed := diffRelations(oldAdj, newAdj)
499	
500		var newNodes, removedNodes, changedNodes []string
501		for name := range newAdj {
502			if oldParents, ok := oldAdj[name]; !ok {
503				newNodes = append(newNodes, name)
504			} else if !stringSliceEqual(oldParents, newAdj[name]) {
505				changedNodes = append(changedNodes, name)
506			}
507		}
508		for name := range oldAdj {
509			if _, ok := newAdj[name]; !ok {
510				removedNodes = append(removedNodes, name)
511			}
512		}
513		sort.Strings(newNodes)
514		sort.Strings(removedNodes)
515		sort.Strings(changedNodes)
516	
517		common := make([]string, 0)
518		for name := range oldAdj {
519			if _, ok := newAdj[name]; ok {
520				common = append(common, name)
521			}
522		}
523		sort.Strings(common)
524	
525		rootChanges := make([]RootSourceChange, 0)
526		for _, name := range common {
527			oldRoots := rootSources(name, oldAdj)
528			newRoots := rootSources(name, newAdj)
529			if !stringSliceEqual(oldRoots, newRoots) {
530				rootChanges = append(rootChanges, RootSourceChange{
531					Dataset:  name,
532					OldRoots: oldRoots,
533					NewRoots: newRoots,
534				})
535			}
536		}
537	
538		return &CompareReport{
539			NewDatasets:       orEmptyStrings(newNodes),
540			RemovedDatasets:   orEmptyStrings(removedNodes),
541			ChangedDatasets:   orEmptyStrings(changedNodes),
542			AddedRelations:    orEmptyRelations(added),
543			RemovedRelations:  orEmptyRelations(removed),
544			RootSourceChanges: rootChanges,
545		}
546	}
547	
548	// adjacencyFromValidFile builds normalized parent adjacency from an already
549	// validated graph file.
550	func adjacencyFromValidFile(gf GraphFile) adjacency {
551		adj := make(adjacency, len(gf.Datasets))
552		for _, ds := range gf.Datasets {
553			adj[ds.Name] = uniqueSorted(ds.Upstreams)
554		}
555		return adj
556	}
557	
558	// rootSources returns the root datasets reachable from node by following
559	// direct upstream edges. A node without upstreams is itself a root and its own
560	// source, so it is included. Nodes reached by more than one path count once.
561	// The result is sorted by name and never nil.
562	func rootSources(node string, adj adjacency) []string {
563		visited := make(map[string]bool)
564		var roots []string
565		var walk func(string)
566		walk = func(current string) {
567			if visited[current] {
568				return
569			}
570			visited[current] = true
571			parents := adj[current]
572			if len(parents) == 0 {
573				roots = append(roots, current)
574				return
575			}
576			for _, parent := range parents {
577				walk(parent)
578			}
579		}
580		walk(node)
581		sort.Strings(roots)
582		return orEmptyStrings(roots)
583	}
584	
585	func orEmptyStrings(s []string) []string {
586		if s == nil {
587			return []string{}
588		}
589		return s
590	}
591	
592	func orEmptyRelations(r []Relation) []Relation {
593		if r == nil {
594			return []Relation{}
595		}
596		return r
597	}
598

